param([string]$ProjectRoot = (Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw 'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework
[Reflection.Assembly]::LoadFrom((Join-Path $halcon 'bin\dotnet35\halcondotnet.dll'))|Out-Null
$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Assert([bool]$ok,[string]$message){if(-not$ok){throw "Assertion failed: $message"}}
function Polygon([double[]]$rows,[double[]]$columns){[HalconDotNet.HObject]$x=$null;[HalconDotNet.HOperatorSet]::GenContourPolygonXld([ref]$x,[HalconDotNet.HTuple]$rows,[HalconDotNet.HTuple]$columns);$x}
function Rectangle([double]$row,[double]$column,[double]$phi,[double]$length1,[double]$length2){[HalconDotNet.HObject]$x=$null;[HalconDotNet.HOperatorSet]::GenRectangle2ContourXld([ref]$x,[HalconDotNet.HTuple]$row,[HalconDotNet.HTuple]$column,[HalconDotNet.HTuple]$phi,[HalconDotNet.HTuple]$length1,[HalconDotNet.HTuple]$length2);$x}
function Concat($objects){[HalconDotNet.HObject]$all=$null;[HalconDotNet.HOperatorSet]::GenEmptyObj([ref]$all);foreach($one in $objects){[HalconDotNet.HObject]$combined=$null;try{[HalconDotNet.HOperatorSet]::ConcatObj($all,$one,[ref]$combined);$all.Dispose();$all=$combined;$combined=$null}finally{if($null-ne$combined){$combined.Dispose()}}};Write-Output -NoEnumerate $all}

$temp=Join-Path ([IO.Path]::GetTempPath()) ('halcon-vm-s52-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$mainType=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$metadataType=$assembly.GetType('HalconWinFormsDemo.Models.ToolMetadata',$true);$snapshotType=$assembly.GetType('HalconWinFormsDemo.Models.VmXldSnapshot',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$static=[Reflection.BindingFlags]'Static,Public'
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$mainType.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function Field([string]$name){$f=$mainType.GetField($name,$all);if($null-eq$f){throw "Missing field $name"};$v=$f.GetValue($window);Write-Output -NoEnumerate $v}
function Tool([string]$kind,[string]$name){$mainType.GetMethod('CreateFlowTool',$private).Invoke($window,[object[]]@([Enum]::Parse($kindType,$kind),$name,$true,$null))}
function Out($tool,[string]$port){$value=$null;if(-not$tool.TryGetOutputValue($port,[ref]$value)){throw "Missing output $port"};$value}

# A: compact selected node and one label per module dependency. S62 intentionally restored the full categorized catalog as the default.
Assert((Field 'toolCatalogMode')-eq'All') 'Toolbox does not default to the full categorized catalog'
$catalogView=Field 'toolCatalogView';$visible=@($catalogView|ForEach-Object{$_});Assert($visible.Count -eq (Field 'toolCatalog').Count) 'Default toolbox does not expose every implemented tool after S62'
$flow=Field 'flowTools';$flow.Clear();$source=Tool RegionFeatureFilter 'Source';$target=Tool RegionSetOperation 'Target';$target.SetInputBinding('RegionA',$source.ToolId,'Region');$target.SetInputBinding('RegionB',$source.ToolId,'Region');$flow.Add($source);$flow.Add($target);$mainType.GetMethod('RefreshFlowPortVisualization',$private).Invoke($window,@())|Out-Null
(Field 'FlowToolList').SelectedItem=$target;$mainType.GetMethod('FlowToolList_SelectionChanged',$private).Invoke($window,[object[]]@((Field 'FlowToolList'),$null))|Out-Null
Assert($target.GraphHeight-eq68) 'Selecting a node still exposes the full port wall'
$connections=Field 'flowConnections';Assert($connections.Count-eq2-and($connections|Where-Object IsLabelVisible).Count-eq0) 'S72 quiet focus should not expand dependency labels for node selection alone'
$mainType.GetField('selectedFlowConnectionKey',$private).SetValue($window,$connections[0].ConnectionKey);$mainType.GetMethod('RefreshFlowPortVisualization',$private).Invoke($window,@())|Out-Null;$connections=Field 'flowConnections';Assert(($connections|Where-Object IsLabelVisible).Count-eq1) 'Explicit connection selection did not expose one merged dependency label'
$target.IsFlowDetailExpanded=$true;$mainType.GetMethod('RefreshFlowPortVisualization',$private).Invoke($window,@())|Out-Null;Assert($target.GraphHeight-gt68) 'Explicit port expansion no longer works'

# B: HALCON main-axis direction, half-turn deviation, instability, output ownership and downstream value.
$kind=[Enum]::Parse($kindType,'XldDirectionConsistencyMeasurement');$inputs=$metadataType.GetMethod('GetInputPorts',$static).Invoke($null,[object[]]@($kind));$outputs=$metadataType.GetMethod('GetOutputPorts',$static).Invoke($null,[object[]]@($kind));Assert(($inputs|Where-Object PortName -eq XLD).Count-eq1-and($outputs|Where-Object PortName -eq AbsoluteDeviation).DataType-eq'Number'-and($outputs|Where-Object PortName -eq XLD).DataType-eq'XLD') 'Typed direction consistency ports missing'
$phi=10*[Math]::PI/180;$rect=Rectangle 100 120 $phi 40 10;$reverse=Rectangle 100 120 ($phi+[Math]::PI) 40 10;$open=Polygon ([double[]]@(0,0,10,10)) ([double[]]@(0,50,50,0));$bowtie=Polygon ([double[]]@(-5,5,-5,5,-5)) ([double[]]@(0,50,50,0,0));$square=Rectangle 40 40 0.5 20 19.9;$degenerate=Polygon ([double[]]@(1,1,1)) ([double[]]@(2,2,2));$input=Concat @($rect,$reverse,$open,$bowtie,$square,$degenerate);foreach($x in @($rect,$reverse,$open,$bowtie,$square,$degenerate)){$x.Dispose()}
$measure=Tool XldDirectionConsistencyMeasurement 'S52 Direction';$run=$mainType.GetMethod('RunXldDirectionConsistencyMeasurementTool',$private);function RunMeasure($x){try{$run.Invoke($window,[object[]]@($measure,$x.PSObject.BaseObject))}catch [Reflection.TargetInvocationException]{throw $_.Exception.InnerException}}
try{$measure.Parameters.XldDirectionContourMode='All';$measure.Parameters.XldDirectionMinimumPointCount=2;$measure.Parameters.XldDirectionClosureTolerance=0;$measure.Parameters.XldDirectionTargetAngleDegrees=0;$measure.Parameters.XldDirectionDeviationMinimum=0;$measure.Parameters.XldDirectionDeviationMaximum=15;$measure.Parameters.XldDirectionMinimumAspectRatio=1.1;$result=RunMeasure $input;Assert($result.ResultCode-eq'OK'-and[int](Out $measure MeasuredCount)-eq4-and[int](Out $measure PassCount)-eq4-and[int](Out $measure FailCount)-eq0) 'Direction pass/fail measurement failed';Assert([int](Out $measure UnstableCount)-eq1-and[int](Out $measure DegenerateCount)-eq1-and[int](Out $measure OpenCount)-eq1) 'Open/near-square/degenerate semantics failed';Assert([Math]::Abs([double](Out $measure AbsoluteDeviation)-10)-lt.05) 'Main-axis angle deviation is incorrect';[HalconDotNet.HObject]$copy=(Out $measure XLD).CreateXldCopy();try{[HalconDotNet.HTuple]$overlayCount=$null;[HalconDotNet.HOperatorSet]::CountObj($copy,[ref]$overlayCount);Assert($overlayCount.I-eq8) 'Rectangle plus axis overlay count is incorrect'}finally{$copy.Dispose()};$old=Out $measure XLD;$measure.Parameters.XldDirectionDeviationMaximum=5;$failed=RunMeasure $input;Assert($failed.ResultCode-eq'NG'-and[int](Out $measure FailCount)-ge2-and$old.IsDisposed) 'Fail decision or old snapshot release failed';[HalconDotNet.HTuple]$sourceCount=$null;[HalconDotNet.HOperatorSet]::CountObj($input,[ref]$sourceCount);Assert($sourceCount.I-eq6) 'Upstream XLD ownership changed'}finally{$input.Dispose()}
$boundary=Rectangle 50 50 (88*[Math]::PI/180) 40 8;try{$measure.Parameters.XldDirectionTargetAngleDegrees=-89;$measure.Parameters.XldDirectionDeviationMaximum=4;$boundaryResult=RunMeasure $boundary;Assert($boundaryResult.ResultCode-eq'OK'-and[Math]::Abs([double](Out $measure SignedDeviation)+3)-lt.05) 'Half-turn target boundary/sign semantics failed'}finally{$boundary.Dispose()}
[HalconDotNet.HObject]$empty=$null;[HalconDotNet.HOperatorSet]::GenEmptyObj([ref]$empty);try{$emptyResult=RunMeasure $empty;Assert($emptyResult.ResultCode-eq'NG'-and[int](Out $measure MeasuredCount)-eq0) 'Empty input semantics failed'}finally{$empty.Dispose()}
$measure.Parameters.XldDirectionMinimumPointCount=1;Assert(-not[string]::IsNullOrWhiteSpace($measure.Parameters.Validate($kind))) 'Invalid point count accepted';$measure.Parameters.XldDirectionMinimumPointCount=2;$measure.Parameters.XldDirectionDeviationMinimum=20;$measure.Parameters.XldDirectionDeviationMaximum=10;Assert(-not[string]::IsNullOrWhiteSpace($measure.Parameters.Validate($kind))) 'Invalid deviation range accepted';$measure.Parameters.XldDirectionDeviationMinimum=0;$measure.Parameters.XldDirectionDeviationMaximum=15
$flow.Clear();$producer=Tool XldPointClosureFilter 'S52 Source';$chain=Tool XldDirectionConsistencyMeasurement 'S52 Direction Chain';$judge=Tool NumericJudge 'S52 Deviation Judge';$chain.SetInputBinding('XLD',$producer.ToolId,'XLD');$judge.SetInputBinding('Value',$chain.ToolId,'AbsoluteDeviation');$judge.InputToolId=$chain.ToolId;$judge.InputPortName='AbsoluteDeviation';$judge.NumericLowerLimit=9;$judge.NumericUpperLimit=11;$flow.Add($producer);$flow.Add($chain);$flow.Add($judge);$sourceXld=Rectangle 200 220 $phi 40 10;try{$producer.SetOutputValue('XLD',$snapshotType.GetMethod('Create',$static).Invoke($null,[object[]]@($sourceXld.PSObject.BaseObject,$producer.ToolId,$producer.InstanceName,'XLD')));$producer.ResultCode='OK'}finally{$sourceXld.Dispose()};$chain.Parameters.XldDirectionTargetAngleDegrees=0;$chain.Parameters.XldDirectionDeviationMaximum=15;$chain.Parameters.XldDirectionMinimumAspectRatio=1.1;$execute=$mainType.GetMethod('ExecuteFlowTool',$private);$execute.Invoke($window,[object[]]@($chain,'S52 chain'))|Out-Null;$execute.Invoke($window,[object[]]@($judge,'S52 chain'))|Out-Null;Assert($chain.ResultCode-eq'OK'-and$judge.ResultCode-eq'OK') 'Real XLD/Number downstream chain failed'
(Field 'FlowToolList').SelectedItem=$measure;$measure.Parameters.XldDirectionContourMode='ClosedOnly';$measure.Parameters.XldDirectionTargetAngleDegrees=22;$measure.Parameters.XldDirectionDeviationMaximum=7;$measure.Parameters.XldDirectionMinimumAspectRatio=1.25;$mainType.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($measure))|Out-Null;Assert((Field 'DockXldDirectionConsistencyPanel').Visibility.ToString()-eq'Visible'-and(Field 'DockXldDirectionTargetAngleTextBox').Text-eq'22') 'Dock configuration synchronization failed';$flow.Add($measure);$recipe=$mainType.GetMethod('CaptureRecipe',$private).Invoke($window,@());$saved=$recipe.ToolFlow|Where-Object{$_.ToolId-eq$measure.ToolId}|Select-Object -First 1;Assert($saved.Parameters.XldDirectionContourMode-eq'ClosedOnly'-and$saved.Parameters.XldDirectionDeviationMaximum-eq7-and$saved.Parameters.XldDirectionMinimumAspectRatio-eq1.25) 'Recipe persistence failed'
$mainType.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
Write-Output 'S52 progressive disclosure and HALCON XLD direction-consistency smoke tests passed'
